"""Present the forward route: macro observations -> statistical structure -> risk."""
from pathlib import Path
import html,re
R=Path(__file__).resolve().parents[1]
def b(en,zh):return '<span data-en>'+en+'</span><span data-zh hidden>'+zh+'</span>'
def p(en,zh):return '<p>'+b(en,zh)+'</p>'
def eq(tex):return '<span class="equation display" data-math="'+html.escape(tex,quote=True)+'"></span>'
def upsert(file,id,section,before):
 path=R/'web'/file;s=path.read_text();pattern=r'<section\b[^>]*\bid="'+id+r'"[\s\S]*?</section>'
 if re.search(pattern,s):s=re.sub(pattern,lambda _:section,s,count=1)
 else:assert before in s;s=s.replace(before,section+before,1)
 path.write_text(s)
steps=[('Macro observations','宏观观测量','Start with price returns, volume, counts and signed aggressor flow—the market quantities available at each time.','从每个时点可获得的收益、成交量、笔数与主动买卖成交流出发。','methods.html#execution-risk-bridge','Define the observable inputs','明确可观测输入'),('Statistical structure','统计结构推断','Use moment relations to estimate activity, size concentration, directional amplification and persistence under explicit model assumptions.','通过矩关系，在明确模型假设下估计活动、大小集中度、方向放大与持续性。','methods.html#inverse','Connect observables to effective structure','连接观测量与有效结构'),('Risk mapping','风险映射与预测','Map flow means and dispersion through price response and residual risk; dynamic extensions carry the estimated structure forward.','通过价格响应和残差风险，将成交流均值与离散程度映射到风险，并用动态扩展描述其后续演化。','methods.html#execution-risk-bridge','From estimated moments to risk','从估计的矩到风险'),('Evaluation and use','检验与应用','Evaluate forecasts at matched input budgets and inspect the mechanism through real-market replay and shared-risk diagnostics.','按相同输入预算检验预测，并用真实回放和共同风险诊断解释机制与应用。','findings.html#information-efficiency','Inspect forecasts and applications','查看预测检验与应用')]
section='<section class="section wrap research-mainline" id="research-mainline"><h2>'+b('From market observations to statistical structure and risk','从宏观观测量，到统计结构，再到风险')+'</h2>'+p('We develop and test a mechanism-based route from a small observable market description to interpretable risk estimates.','我们构建并检验一条机制驱动的路线：从少量可观测市场信息，得到可解释的风险估计。')+'<ol class="mainline-steps">'
for en,zh,desc,dzh,url,status,szh in steps:section+='<li><h3>'+b(en,zh)+'</h3>'+p(desc,dzh)+'<a href="'+url+'">'+b(status,szh)+'</a></li>'
section+='</ol><div class="mainline-application">'+p('The microscopic model explains why these aggregate moments contain information about collective trading. Assumption diagnostics guide extensions of the measurement and dynamic model; the central task remains inference and risk prediction.','微观模型解释这些聚合矩为何包含集体交易的信息。假设诊断用于指导测量与动态模型的扩展；核心任务始终是统计结构推断与风险预测。')+'<a class="text-link" href="trading.html">'+b('Inspect observations, structure and risk in the replay','在回放中对照观测量、统计结构与风险')+'</a></div></section>'
upsert('index.html','research-mainline',section,'<section class="research-intro"')
section='<section class="section reading" id="execution-risk-bridge"><h2>'+b('Observable market statistics, effective structure and risk','市场观测统计、有效结构与风险')+'</h2>'+p('The inputs are log returns r, traded volume V, trade counts K and signed aggressor flow F. The inferential task is to extract risk-relevant size, directional and temporal structure from these observations. Shared trading decisions provide a microscopic explanation for the moment relations used in that inference.','输入是对数收益r、成交量V、成交笔数K和有方向的主动成交流F。推断任务是从这些观测中提取与风险有关的大小、方向及时间结构；共同交易决策为这些矩关系提供微观解释。')
section+='<h3>'+b('Measure the inputs and define the size baseline','测量输入，定义成交大小基线')+'</h3>'+eq(r'F_t=\sum_i\epsilon_{it}v_{it},\qquad B_t=\sum_i v_{it}^2')+p('F is aggressive buy volume minus aggressive sell volume. B measures execution-size concentration: at the same total volume, larger concentrated executions raise the sum of squares. Detailed executions allow B to be measured directly; macro-only deployment requires a specified size model and calibration to estimate it.','F是主动买入量减去主动卖出量。B刻画成交大小集中度：总量相同，越集中成大单，平方和越大。完整成交记录可以直接测量B；仅使用宏观量部署时，需要给定大小模型并校准估计。')
section+='<h3>'+b('Infer effective directional and temporal structure','推断有效方向结构与时间结构')+'</h3>'+eq(r'\widehat G_t=\frac{\widehat{\operatorname{Var}}_{15}(F)}{\overline B_{15}}')+p('Under independent symmetric execution signs, the size baseline sets the reference flow second moment. The centred ratio G compares observed dispersion with that reference. Together with mean flow, size concentration and persistence, it gives an effective statistical description for the risk map. Interpreting it as group susceptibility additionally requires a participant/execution map and mark assumptions.','在独立对称成交方向假设下，大小基线给出参考成交流二阶矩。中心化比值G比较观测离散程度与该参照；结合平均成交流、大小集中度和持续性，可形成进入风险映射的有效统计描述。若进一步解释成群体易感性，还需参与者与执行单位的对应及大小标记假设。')
section+=eq(r'\overline B_{15}\widehat G_t=\widehat{\operatorname{Var}}_{15}(F)')+p('The same-window identity shows exactly what information the decomposition contains. Dynamic restrictions—such as faster activity changes and slower amplification—specify how the estimated structure is carried into a forecast. Their value is assessed against direct-flow and equally informed statistical controls.','同窗口恒等式明确了这一分解所包含的信息。活动变化较快、放大变化较慢等动态约束，进一步规定如何将估计结构延续到预测；其作用通过直接成交流及同信息统计对照检验。')
section+='<h3>'+b('Predict risk through the price response','通过价格响应预测风险')+'</h3>'+eq(r'r_t=\alpha+\beta F_t+\eta_t,\qquad\beta\geq0')+eq(r'\widehat h_{t+1|t}=(\alpha+\beta\overline F_{15})^2+\beta^2\overline B_3\widehat G_t+\sigma_\eta^2')+p('The risk map combines the mean-return term, flow dispersion and residual risk. In the replay, response coefficients use the 30 completed minutes up to play and stay fixed. Three-minute activity and 15-minute amplification form a local version of the fast/slow hypothesis; RMS estimates are labelled separately from observed trailing fluctuation.','风险映射结合平均收益项、成交流离散程度和残差风险。回放仅用截至开局的30个完整分钟校准响应系数，局中固定；3分钟活动与15分钟放大构成快慢假设的局部版本，RMS估计与已经发生的波动分别标注。')
section+=p('The debrief uses detailed executions as a measured reference for the size baseline. The deployable macro-inference question and the daily matched-budget forecast evaluation retain their own input and time protocols. Current Bitcoin evaluation has not established an accuracy or information-efficiency advantage.','复盘使用完整成交作为大小基线的测量参照；可部署的宏观反演与日频同预算预测，分别遵循各自的输入和时间协议。目前Bitcoin评估尚未建立精度或信息效率优势。')
section+='<h3>'+b('Check assumptions and extend the statistical model','检查假设，扩展统计模型')+'</h3>'+p('Joint-moment compatibility, execution-size distributions, fragmentation and state dependence are complementary diagnostics. They guide weighted and dynamic extensions while preserving the observable → statistical structure → risk route. Coupled fast/slow states provide a controllable mechanism for persistence and switching.','联合矩兼容性、成交大小分布、执行碎片化与状态依赖是相互补充的诊断。它们指导加权和动态扩展，同时保持观测量→统计结构→风险这条路线。快慢耦合状态为持续性与方向切换提供可控机制。')+'<div class="collective-links"><a href="#delta">'+b('Joint-moment diagnostic','联合矩假设诊断')+'</a><a href="trading.html">'+b('Inspect the real-market debrief','查看真实回放复盘')+'</a><a href="findings.html#information-efficiency">'+b('Read the forecast comparison','查看风险预测比较')+'</a></div></section>'
upsert('methods.html','execution-risk-bridge',section,'<section class="section reading" id="references"')
# Keep the detailed diagnostic available at its own anchor, after the core route.
path=R/'web/methods.html';s=path.read_text();delta=re.search(r'<section\b[^>]*id="delta"[\s\S]*?</section>',s).group(0)
delta=delta.replace('A necessary restriction from shared activity','A joint-moment assumption diagnostic').replace('共同活动给出的必要约束','联合矩假设诊断')
if 'id="delta-derivation"' not in delta:
 head,body=delta.split('</h2>',1);body=body.rsplit('</section>',1)[0]
 slash=chr(92)
 body=body.replace('data-math="A=', 'data-math="A_'+slash+'Delta=').replace('data-math="B=', 'data-math="B_'+slash+'Delta=').replace(slash+'frac{A-B}',slash+'frac{A_'+slash+'Delta-B_'+slash+'Delta}').replace('gives A and B.','gives the diagnostic ratios AΔ and BΔ.').replace('得到A和B。','得到诊断比值AΔ与BΔ。')
 delta=head+'</h2>'+p('One compatibility check uses a normalized joint-moment statistic Δ. Its role is to test the fixed measurement/action assumptions alongside size, fragmentation and state diagnostics. The subscripted ratios below are distinct from the execution-size baseline B used in the risk map.','归一化联合矩统计量Δ提供一项兼容性检查，与大小、碎片化及状态诊断共同检验固定测量与动作假设。下面带Δ下标的诊断比值，与风险映射中的成交大小基线B不同。')+'<details id="delta-derivation"><summary>'+b('Derivation and market evidence','展开推导与市场证据')+'</summary>'+body+'</details></section>'
delta=delta.replace(chr(92)*2+'Delta',chr(92)+'Delta').replace(chr(92)+'frac{A-B}',chr(92)+'frac{A_'+chr(92)+'Delta-B_'+chr(92)+'Delta}')
s=re.sub(r'<section\b[^>]*id="delta"[\s\S]*?</section>','',s,count=1)
s=s.replace('<section class="section reading" id="references"',delta+'<section class="section reading" id="references"',1)
# The macro-to-risk overview is the methods entry point.
bridge=re.search(r'<section\b[^>]*id="execution-risk-bridge"[\s\S]*?</section>',s).group(0);s=s.replace(bridge,'',1);s=s.replace('<section class="section reading" id="mechanism"',bridge+'<section class="section reading" id="mechanism"',1);path.write_text(s)
# Forecasts are the main empirical evaluation; the compatibility example follows them.
path=R/'web/findings.html';s=path.read_text();market=re.search(r'<section\b[^>]*id="market"[\s\S]*?</section>',s).group(0);market=market.replace('Market observations test the fixed interface','Checking the working assumptions').replace('市场观测检验固定接口','检验工作假设');s=s.replace(re.search(r'<section\b[^>]*id="market"[\s\S]*?</section>',s).group(0),'',1);s=s.replace('<section class="closing"',market+'<section class="closing"',1)
note='<div class="forecast-mainline-note">'+p('The HAR feature benchmark is a statistical comparator. Mechanism-derived risk estimates are evaluated under matched information budgets in the linked study; the score and input protocols are kept distinct.','HAR特征基准提供统计参照；机制风险估计在链接的研究中按相同信息预算评价，分数与输入协议分别记录。')+'<a href="#information-efficiency">'+b('Mechanism-based risk evaluation','机制风险估计的评价')+'</a></div>'
s=re.sub(r'<div class="forecast-mainline-note">[\s\S]*?</div>','',s);s=re.sub(r'(<section[^>]*id="forecast"[^>]*>)',lambda m:m.group(0)+note,s,count=1);path.write_text(s)
# Surface the macro-observation question in the opening paragraph.
path=R/'web/index.html';s=path.read_text();s=s.replace('We study how coordinated trading shapes market fluctuations and what aggregate price and volume can reveal about the underlying network.','We study how macro market observations reveal effective collective trading structure, and how that structure enters risk estimates.').replace('我们研究共同交易行为如何形成市场波动，以及聚合后的价格与成交量能够揭示哪些网络信息。','我们研究宏观市场观测能够揭示哪些有效集体交易结构，以及这些结构如何进入风险估计。');path.write_text(s)
# Read mechanism-derived evaluation before the statistical comparator and applications.
path=R/'web/findings.html';s=path.read_text();m=re.search(r'<section\b[^>]*id="information-efficiency"[\s\S]*?</section>',s)
if m:
 section=m.group(0);s=s.replace(section,'',1);s=re.sub(r'(<section[^>]*id="forecast"[^>]*>)',lambda m:section+m.group(0),s,count=1)
path.write_text(s)
